CREATE OR REPLACE FUNCTION public.contractor_assign_trip(_trip uuid,_contractor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.trips;src uuid;target_user uuid;BEGIN SELECT * INTO t FROM public.trips WHERE id=_trip FOR UPDATE;IF t.id IS NULL OR t.status IN ('completed','canceled','cancelled','no_show') OR t.trip_kind<>'passenger' OR t.transport_type<>'ambulatory' OR t.network_provider_workspace_id IS NOT NULL THEN RAISE EXCEPTION 'Assignable owned ambulatory trip required';END IF;SELECT workspace_id INTO src FROM public.ride_requests WHERE id=t.ride_request_id;IF src IS NULL THEN SELECT m.workspace_id INTO src FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=t.created_by AND m.role='owner' AND m.removed_at IS NULL AND w.provider_subtype='nemt_business';END IF;IF NOT public.network_workspace_access(src,true) OR NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=src AND user_id=auth.uid() AND role IN ('owner','admin') AND NOT is_contractor AND removed_at IS NULL) OR NOT public.contractor_connected(src,_contractor) OR NOT public.pass4p_service_eligible(_contractor,'ambulatory') THEN RAISE EXCEPTION 'Active connected eligible contractor and business manager required';END IF;SELECT user_id INTO target_user FROM public.workspace_members WHERE workspace_id=_contractor AND role='owner' AND NOT is_contractor AND removed_at IS NULL;IF target_user IS NULL THEN RAISE EXCEPTION 'Contractor owner unavailable';END IF;PERFORM set_config('app.contractor_assignment','true',true);UPDATE public.trips SET assigned_to=target_user,contractor_assigned_workspace_id=_contractor,driver_id=NULL,vehicle_id=NULL WHERE id=_trip;INSERT INTO public.trip_dispatch_events(trip_id,event_type,vendor,payload) VALUES(_trip,'contractor_assigned','mfn',jsonb_build_object('actor_id',auth.uid(),'contractor_workspace_id',_contractor,'source_workspace_id',src));END $$;
CREATE FUNCTION public.contractor_assignment_options(_trip uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.trips;src uuid;BEGIN SELECT * INTO t FROM public.trips WHERE id=_trip;IF t.id IS NULL OR t.transport_type<>'ambulatory' OR t.trip_kind<>'passenger' OR t.status IN ('completed','canceled','cancelled','no_show') OR t.network_provider_workspace_id IS NOT NULL THEN RETURN '[]';END IF;SELECT workspace_id INTO src FROM public.ride_requests WHERE id=t.ride_request_id;IF src IS NULL THEN SELECT m.workspace_id INTO src FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=t.created_by AND m.role='owner' AND m.removed_at IS NULL AND w.provider_subtype='nemt_business';END IF;IF NOT public.network_workspace_access(src,true) OR NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=src AND user_id=auth.uid() AND role IN ('owner','admin') AND NOT is_contractor AND removed_at IS NULL) THEN RETURN '[]';END IF;RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('workspace_id',w.id,'business_name',w.display_name)),'[]') FROM public.workspaces w WHERE w.provider_subtype='independent_contractor' AND public.contractor_connected(src,w.id) AND public.pass4p_service_eligible(w.id,'ambulatory'));END $$;
REVOKE ALL ON FUNCTION public.contractor_assignment_options(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_assignment_options(uuid) TO authenticated,service_role;
CREATE POLICY contractor_private_credentials ON public.provider_credentials AS RESTRICTIVE FOR SELECT TO authenticated USING(kind NOT IN ('driver_license','auto_insurance','w9') OR provider_user_id=auth.uid());
CREATE FUNCTION public.contractor_subscription_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.membership_kind='contractor' AND (NEW.status='trialing' OR (NEW.workspace_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=NEW.workspace_id AND provider_subtype='independent_contractor'))) THEN RAISE EXCEPTION 'Contractor subscriptions require matching subtype and no trial';END IF;RETURN NEW;END $$;
CREATE TRIGGER contractor_subscription_guard BEFORE INSERT OR UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.contractor_subscription_guard();